"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[15351],{75301:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Factions","desc":"Combat faction policy shared by client and server. Resolves a Player or a\\nHumanoid-bearing Model to a `Faction`, and decides whether one faction may\\ndamage another via a default-deny hostility table.\\n\\nFaction comes from: a Player (or a Model that is a player\'s character) \u2192\\n\\"Player\\"; a Model tagged `EnemyTag` \u2192 \\"Enemy\\"; a Model tagged `FriendlyTag`\\n\u2192 \\"Friendly\\". These two tags REPLACE the former single \\"NPC\\" tag \u2014 being\\neither tag marks a Model as a combatant (damageable + collision pass-through;\\nsee NpcCollisionService).\\n\\nOnly Player<->Enemy damage is allowed. Every other ordered pair is denied,\\nso there is no player-vs-player or enemy-vs-enemy damage, and friendly NPCs\\n(e.g. the trader) cannot be damaged by anyone.\\n\\nThe actual block is enforced server-side in CombatService; this module is\\nshared so the client can reuse `resolve` for UI (e.g. hitmarker suppression).","source":{"line":23,"path":"src/ReplicatedStorage/SharedModules/Factions.luau"}}')}}]);